export interface LlmHealth {
  healthy: boolean;
  message: string;
}

export interface McpHealth {
  reachable: boolean;
}

/**
 * A turn is an ordered sequence of parts, so a card can sit between two
 * paragraphs exactly where the agent put it. `content` stays as the combined
 * prose because that is what gets replayed as conversation history.
 */
export type ChatPart =
  | { kind: "text"; text: string }
  | { kind: "ui"; id: string; node: UiNode };

export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  parts: ChatPart[];
}

export interface ChatStreamRequest {
  base_url: string;
  api_key: string;
  model: string;
  mcp_url: string;
  messages: Pick<ChatMessage, "role" | "content">[];
  /** What this client can render. Omitted by non-visual clients. */
  ui_catalog?: UiCatalogManifest;
  conversation_id?: string | null;
}

export type ObservationKind =
  | "career"
  | "opportunity"
  | "business"
  | "stakeholder"
  | "constraint"
  | "evidence"
  | "preference";

export type ObservationStatus = "suggested" | "confirmed" | "dismissed";

export interface Observation {
  id: string;
  kind: ObservationKind;
  text: string;
  data: Record<string, unknown>;
  status: ObservationStatus;
  confidence: number | null;
  source_turn: number | null;
  created_at: string;
  updated_at: string;
}

export type StoredChatPart =
  | { kind: "text"; text: string }
  | { kind: "ui"; id: string; spec: unknown };

export interface StoredTurn {
  id: number;
  role: "user" | "assistant";
  content: string;
  parts: StoredChatPart[];
  created_at: string;
}

export interface StoredConversation {
  id: string;
  started_at: string;
  updated_at: string;
